  DL.conceptById = {};
  DL.conceptBySlug = {};
  DL.concepts.forEach(function(c){ DL.conceptById[c.id]=c; DL.conceptBySlug[c.slug]=c; });
  DL.domains = [];
  var seen={};
  DL.concepts.forEach(function(c){ if(!seen[c.domain]){seen[c.domain]=1;DL.domains.push(c.domain);} });
  DL.conceptsByDomain = function(d){ return DL.concepts.filter(function(c){return c.domain===d;}); };
